import{_ as a,o as i,c as t,a0 as n}from"./chunks/framework.B7o6dWmz.js";const h=JSON.parse('{"title":"Features","description":"","frontmatter":{},"headers":[],"relativePath":"guide/features.md","filePath":"guide/features.md","lastUpdated":1793979958000}'),r={name:"guide/features.md"};function l(o,e,s,d,c,u){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h1><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><ul><li>OpenAI: Chat Completions, Responses, Embeddings, Images, Audio, Rerank</li><li>Anthropic Messages and native Gemini</li><li>Conversion between the three protocols <strong>in any direction</strong>, preserving tool calls, images, thinking and cache usage; streaming and non-streaming</li><li>Claude Code and official SDKs work out of the box</li></ul><h2 id="upstreams-and-routing" tabindex="-1">Upstreams and routing <a class="header-anchor" href="#upstreams-and-routing" aria-label="Permalink to &quot;Upstreams and routing&quot;">​</a></h2><ul><li>Upstream types: OpenAI-compatible (including other relays), Azure OpenAI, Anthropic, Gemini, AWS Bedrock, Vertex AI</li><li>Priority + weight routing with automatic failover; when an upstream says &quot;no such model&quot;, the request moves to another channel instead of failing</li><li>Automatic key suspension and cooldown, scheduled latency probes, long answers never cut off</li><li>Outbound address checks against SSRF</li></ul><h2 id="pricing-and-ledger" tabindex="-1">Pricing and ledger <a class="header-anchor" href="#pricing-and-ledger" aria-label="Permalink to &quot;Pricing and ledger&quot;">​</a></h2><ul><li>Anchored to the official price: site, group and negotiated prices (see <a href="./pricing">Pricing and margin</a>)</li><li>Real cost per channel; loss-making prices can&#39;t be saved; pricing health check and profit dashboard</li><li>Per-token, per-call and long-context tiers; cache reads and writes priced separately</li><li>Two-phase ledger: reserve → settle, crash recovery, manual review for unclear cases</li><li>Scheduled official price sync and calibration, full price history</li></ul><h2 id="admin-console" tabindex="-1">Admin console <a class="header-anchor" href="#admin-console" aria-label="Permalink to &quot;Admin console&quot;">​</a></h2><ul><li>Gateway overview: revenue, cost, margin, daily trend, top models and users, channel health</li><li>Negotiated pricing: find a user, set &quot;N% of official&quot; per model or in bulk, see the margin live</li><li>Billing group decided by API key: dedicated lines and special rates attach to a specific key</li><li>Usage logs, settlement review, balance ledger</li><li>Menu- and button-level permissions with four preset roles (gateway ops, finance, support, read-only); admin 2FA and IP allowlist</li><li>Prometheus metrics</li></ul><h2 id="for-users" tabindex="-1">For users <a class="header-anchor" href="#for-users" aria-label="Permalink to &quot;For users&quot;">​</a></h2><ul><li>Sign-up and login: username + password, SMS code, email password reset</li><li>Self-service API keys: budget, expiry, model scope, IP allowlist; <strong>a key is shown only once at creation</strong> and only its hash is stored</li><li>Model and price list, usage and billing, integration guide</li></ul><h2 id="payments" tabindex="-1">Payments <a class="header-anchor" href="#payments" aria-label="Permalink to &quot;Payments&quot;">​</a></h2><ul><li>Manual top-up by admins, redemption codes</li><li>Online payment: Alipay and aggregated payment providers, extensible; payment secrets are write-only</li><li>Referral rewards</li></ul><h2 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h2><ul><li>A single native executable, no JVM at runtime</li><li>PostgreSQL; Redis optional</li><li>Official backup script and timer, with optional sync to object storage</li></ul><h2 id="not-supported-yet" tabindex="-1">Not supported yet <a class="header-anchor" href="#not-supported-yet" aria-label="Permalink to &quot;Not supported yet&quot;">​</a></h2><ul><li>Task-style APIs such as Midjourney, Suno and video generation</li><li>Third-party login for users (GitHub, OIDC…)</li><li>Databases other than PostgreSQL</li></ul>',17)])])}const m=a(r,[["render",l]]);export{h as __pageData,m as default};
